// Generated by vibelang from bench/resources.ts; the migrate flow writes it again with each batch.
import { Effect, Metric } from "effect";
/** Acquire a group for a benchmark, then release it after its work settles. */
export const usingResources = (acquire, release, count, body) => Effect.scoped(Effect.flatMap(Effect.all(Array.from({ length: count }, () => Effect.acquireRelease(acquire.pipe(Effect.tap(() => Metric.update(acquired, 1))), (resource) => release(resource).pipe(Effect.ensuring(Metric.update(released, 1))))), { concurrency: "unbounded" }), body)).pipe(Effect.withSpan("bench.resources"));
const acquired = Metric.counter("bench_resources_acquired");
const released = Metric.counter("bench_resources_released");
/** Start the follower before launching the browser, and release both after the run. */
export const usingPair = (first, releaseFirst, second, releaseSecond, body) => usingResources(first, releaseFirst, 1, () => usingResources(second, releaseSecond, 1, ([resource]) => body(resource)));
